  "Unable to load automatic replies.": { de: "Automatische Antworten konnten nicht geladen werden.", fr: "Impossible de charger les réponses automatiques.", ar: "تعذر تحميل الردود التلقائية." },
  "Unable to save automatic replies.": { de: "Automatische Antworten konnten nicht gespeichert werden.", fr: "Impossible d’enregistrer les réponses automatiques.", ar: "تعذر حفظ الردود التلقائية." },
  "Google Group automatic replies must be managed in Google Workspace.": { de: "Automatische Antworten für Google Groups müssen in Google Workspace verwaltet werden.", fr: "Les réponses automatiques des groupes Google doivent être gérées dans Google Workspace.", ar: "يجب إدارة الردود التلقائية لمجموعات Google في Google Workspace." },
  "Shared mailbox automatic replies must be managed by a Microsoft 365 administrator.": { de: "Automatische Antworten für freigegebene Postfächer müssen von einem Microsoft-365-Administrator verwaltet werden.", fr: "Les réponses automatiques des boîtes partagées doivent être gérées par un administrateur Microsoft 365.", ar: "يجب أن يدير مسؤول Microsoft 365 الردود التلقائية لصناديق البريد المشتركة." },
  "Reconnect Gmail once to allow Multideck to manage automatic replies.": { de: "Verbinde Gmail einmal neu, damit Multideck automatische Antworten verwalten kann.", fr: "Reconnectez Gmail une fois pour permettre à Multideck de gérer les réponses automatiques.", ar: "أعد ربط Gmail مرة واحدة للسماح لـ Multideck بإدارة الردود التلقائية." },
  "Reconnect Outlook once to allow Multideck to manage automatic replies.": { de: "Verbinde Outlook einmal neu, damit Multideck automatische Antworten verwalten kann.", fr: "Reconnectez Outlook une fois pour permettre à Multideck de gérer les réponses automatiques.", ar: "أعد ربط Outlook مرة واحدة للسماح لـ Multideck بإدارة الردود التلقائية." },
