  "Messages with this folder or label will appear here.": { de: "Nachrichten in diesem Ordner oder mit diesem Label werden hier angezeigt.", fr: "Les messages associés à ce dossier ou à ce libellé apparaîtront ici.", ar: "ستظهر هنا الرسائل الموجودة في هذا المجلد أو التي تحمل هذا التصنيف." },
  "Opening this conversation...": { de: "Konversation wird geöffnet...", fr: "Ouverture de cette conversation...", ar: "جارٍ فتح هذه المحادثة..." },
  "Unknown sender": { de: "Unbekannter Absender", fr: "Expéditeur inconnu", ar: "مُرسل غير معروف" },
  "Dexter summary": { de: "Dexter-Zusammenfassung", fr: "Résumé de Dexter", ar: "ملخّص Dexter" },
